fn build_command() -> Command {
    Command::new("codesnap")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("from-file").short('f').long("from-file").value_name("FROM_FILE").help("Path to the file to snapshot"))
        .arg(Arg::new("from-code").short('c').long("from-code").value_name("Code").num_args(0..=1).default_missing_value("").help("Code snippet for snapshot"))
        .arg(Arg::new("from-image").short('i').long("from-image").value_name("Image").num_args(0..=1).default_missing_value("").help(""))
        .arg(Arg::new("from-clipboard").long("from-clipboard").action(ArgAction::SetTrue).help(""))
        .arg(Arg::new("output").short('o').long("output").value_name("OUTPUT").required(true).help("Output path for the snapshot. Available value:\n\n- clipboard: Copy the snapshot to clipboard - file path: Save the snapshot to the file path\n\nCurrently CodeSnap supports SVG format and PNG format If output is directory, CodeSnap will generate a temporary file name to save the snapshot to the directory."))
        .arg(Arg::new("silent").long("silent").action(ArgAction::SetTrue).help(""))
        .arg(Arg::new("execute").short('e').long("execute").value_name("EXECUTE").num_args(1..).action(ArgAction::Append).help("Executing a command and taking the output as the code snippet"))
