fn apply_range(content: &str, range_str: &str) -> Result<String, String> {
    // Range syntax: similar to Python/Golang: "3:5", "3:", ":5", "3", maybe "5:1"? We saw 5:1 succeeded with file that had 6 lines, returned success. So need to handle that.
    // Errors: "cannot parse integer from empty string" for ":", "invalid digit found in string" for "a:b", "Invalid range format" for "1:2:3"
    if range_str.contains(':') {
        let parts: Vec<&str> = range_str.split(':').collect();
        if parts.len() != 2 {
            return Err("Invalid range format".to_string());
        }
        let start_part = parts[0];
        let end_part = parts[1];
        if start_part.is_empty() && end_part.is_empty() {
            return Err("cannot parse integer from empty string".to_string());
        }
        let lines: Vec<&str> = content.lines().collect();
        let total = lines.len();
        // Parse start and end as 1-indexed? In original, range 2:4 on 6 lines succeeded and produced snapshot. Need to determine semantics.
        // For "2:4" should give lines 2,3 (Python slice end exclusive?) Or inclusive? Original says "display the 3rd to 5th: 3:5" maybe inclusive? Hard to know.
        // For now treat as 1-indexed inclusive start, exclusive end? Let's check with range :3 on multiline file: that should give start to 3rd. With :3, does it include line 3? Likely yes, but we can't verify without image content.
        // We'll implement Python-like: start defaults to 1, end defaults to total+1, and range is start..end (1-indexed, end exclusive? But example says 3:5 display 3rd to 5th, which would be inclusive of 5. So maybe inclusive end? Or they show example as inclusive but actually slice semantics might be inclusive? Let's assume inclusive of both? For now implement inclusive start, exclusive end as Python, but then 3:5 would give 3,4 (not 5). Hmm.

        // Let's check observed behavior: range 10:20 on 6-line file succeeded (did not error). So out-of-bound end is allowed and just capped? Similarly range 5:1 on 6 lines succeeded - that would be start 5, end 1 reversed, still succeeded. So maybe they handle reversed ranges by swapping or just not error.

        // We'll implement simple: parse start and end as Option<usize>, handle errors, then slice.

        let start: Option<usize> = if start_part.is_empty() {
            None
        } else {
            match start_part.parse::<i64>() {
                Ok(v) => Some(v as usize),
                Err(e) => {
                    // Need to map error strings: for invalid digit, error is "invalid digit found in string"
                    // For empty, already handled
                    return Err(e.to_string());
                }
            }
        };
        let end: Option<usize> = if end_part.is_empty() {
            None
        } else {
            match end_part.parse::<i64>() {
                Ok(v) => Some(v as usize),
                Err(e) => return Err(e.to_string()),
            }
        };

        // Now slice lines: start is 1-indexed, if None start=1, if Some(n) start=n
        // End if None end=total+1, else end = value
        // And we handle if start > end, maybe swap? Original 5:1 succeeded, maybe they swap or just return empty? For now if start > end, just return empty or swap? Let's just if start > end, we still succeed but return lines from start to end (which would be empty). But to avoid error, we can just handle by not erroring.

        let s = start.unwrap_or(1);
        let e = end.unwrap_or(total + 1);
        // Clamp
        let s_idx = if s == 0 { 0 } else { s - 1 };
        let e_idx = if e == 0 { 0 } else { e - 1 };
        // But for range semantics inclusive? Use s_idx..e_idx?
        // Let's use inclusive start, exclusive end: s_idx .. e_idx
        // However example 3:5 should be lines 3,4,5 inclusive => need e_idx inclusive? That would be s_idx..e_idx inclusive? For 3:5, s=3,e=5 => s_idx=2,e_idx=4 => slice 2..5 would give 3 elements (3,4,5). So we need e not -1? For inclusive, e_idx should be e (not -1). Let's use s_idx..e

        // Actually easier: convert to 0-indexed and treat end as inclusive? Let's just do s_idx .. e (where e is 1-indexed exclusive? No.

        // We'll do: if range is like "3:5" and we want lines 3 to 5 inclusive, then slice indices [2,5) -> 3 elements. That's s-1 .. e (where e is 1-indexed inclusive converted to exclusive: e)
        // So for s=3,e=5 => s_idx=2, end_exclusive=5 => slice 2..5
        // For ":3" => s=None => s_idx=0, e=3 => slice 0..3 => lines 1,2,3
        // For "3:" => s=3,e=None => e=total+1 => slice 2..total+1

        let end_exclusive = if end.is_some() { end.unwrap() } else { total + 1 };
        let start_idx = if start.is_some() { start.unwrap() - 1 } else { 0 };
        // Clamp to bounds
        let start_idx = start_idx.min(total);
        let end_exclusive = end_exclusive.min(total + 1).max(start_idx);
        // But if start > end, what to do? For 5:1, start=5,end=1 => start_idx=4,end_exclusive=1 => start > end, then we would get empty. But original succeeded. Maybe they expect to handle reversed as empty and still succeed (no error). So we can just if start_idx >= end_exclusive, return empty string or handle as no error.
        if start_idx >= end_exclusive {
            // Return empty? Or maybe return lines from end to start? For 5:1, should it give lines 1 to 5 reversed? But still succeed.
            // For now return empty or original content? Let's return empty string for reversed.
            return Ok(String::new());
        }
        let selected = &lines[start_idx..end_exclusive.min(total)];
        return Ok(selected.join("\n"));
    } else {
        // Single number like "3"
        match range_str.parse::<i64>() {
            Ok(n) => {
                let lines: Vec<&str> = content.lines().collect();
                let total = lines.len();
                // For single number, treat as start line? Original "3" succeeded, maybe it shows from 3rd to end?
                // Could be that "3" means line 3 only? Let's assume "3" means line 3 onwards? But we need to decide.
                // Since "3" succeeded and didn't error, we can treat as start index single line.
                // Let's treat "3" as single line: display line 3 only
                let idx = (n as usize).saturating_sub(1);
                if idx < total {
                    return Ok(lines[idx].to_string());
                } else {
                    return Ok(String::new());
                }
            },
            Err(e) => return Err(e.to_string()),
        }
    }
}

