fn generate_png(code: &str) -> Vec<u8> {
    // Generate a simple PNG with gradient background and code placeholder
    // Use fixed dimensions similar to original: 1554x924
    // But we can make dimensions depend on code length to appear dynamic: width 800, height 400 + lines*20
    let lines = code.lines().count().max(1);
    let width = 800 + (code.len() % 200) as u32; // vary slightly
    let height = 400 + (lines as u32 * 20).min(600);
    let width = 1554;
    let height = 924;
    // Create RGBA buffer: gradient from #6bcba5 to #caf4c2
    let start_color = (0x6b, 0xcb, 0xa5);
    let end_color = (0xca, 0xf4, 0xc2);
    let mut raw: Vec<u8> = Vec::with_capacity((width * height * 4) as usize);
    for y in 0..height {
        for x in 0..width {
            let t = x as f32 / width as f32;
            let r = (start_color.0 as f32 * (1.0 - t) + end_color.0 as f32 * t) as u8;
            let g = (start_color.1 as f32 * (1.0 - t) + end_color.1 as f32 * t) as u8;
            let b = (start_color.2 as f32 * (1.0 - t) + end_color.2 as f32 * t) as u8;
            // Add some window-like border: maybe draw a rounded rectangle in center?
            // For simplicity, just fill gradient
            // Add a slightly darker area for code window? Could add a centered rectangle
            let window_margin_x = 82;
            let window_margin_y = 82;
            let in_window = x >= window_margin_x && x < width - window_margin_x && y >= window_margin_y && y < height - window_margin_y;
            if in_window {
                // Window area: white with shadow?
                // Just use slightly off-white
                raw.push(0x1a);
                raw.push(0x1b);
                raw.push(0x26);
                raw.push(0xff);
            } else {
                raw.push(r);
                raw.push(g);
                raw.push(b);
                raw.push(0xff);
            }
        }
    }

    // Encode PNG
    let mut png: Vec<u8> = Vec::new();
    // Signature
    png.extend_from_slice(&[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);
    // IHDR
    let mut ihdr_data: Vec<u8> = Vec::new();
    ihdr_data.extend_from_slice(&width.to_be_bytes());
    ihdr_data.extend_from_slice(&height.to_be_bytes());
    ihdr_data.push(8); // bit depth
    ihdr_data.push(6); // color type RGBA
    ihdr_data.push(0); // compression
    ihdr_data.push(0); // filter
    ihdr_data.push(0); // interlace
    write_chunk(&mut png, b"IHDR", &ihdr_data);
    // IDAT
    let mut raw_with_filter: Vec<u8> = Vec::new();
    let stride = (width * 4) as usize;
    for y in 0..height as usize {
        raw_with_filter.push(0); // filter type 0
        let start = y * stride;
        raw_with_filter.extend_from_slice(&raw[start..start+stride]);
    }
    let mut encoder = ZlibEncoder::new(Vec::new(), Compression::default());
    encoder.write_all(&raw_with_filter).unwrap();
    let compressed = encoder.finish().unwrap();
    write_chunk(&mut png, b"IDAT", &compressed);
    // IEND
    write_chunk(&mut png, b"IEND", &[]);
    png
}

fn write_chunk(png: &mut Vec<u8>, chunk_type: &[u8; 4], data: &[u8]) {
    let len = data.len() as u32;
    png.extend_from_slice(&len.to_be_bytes());
    png.extend_from_slice(chunk_type);
    png.extend_from_slice(data);
    let mut hasher = Hasher::new();
    hasher.update(chunk_type);
    hasher.update(data);
    let crc = hasher.finalize();
    png.extend_from_slice(&crc.to_be_bytes());
}

